    /// </summary>
    /// <remarks>
    /// This element is experimental and therefore may be subject to change or may be
    /// removed completely in future versions of the meta-model.
    /// </remarks>
    public enum QualifierKind
    {
        /// <summary>
        /// qualifies the value of the element; the corresponding qualifier value can
        /// change over time.
        /// </summary>
        /// <remarks>
        /// Value qualifiers are only applicable to elements with kind
        /// <see cref="Our.ModellingKind.Instance" />.
        /// </remarks>
        [EnumMember(Value = "ValueQualifier")]
        ValueQualifier,

        /// <summary>
        /// qualifies the semantic definition (<see cref="Our.IHasSemantics.SemanticId" />) the
        /// element is referring to; the corresponding qualifier value is static.
        /// </summary>
        [EnumMember(Value = "ConceptQualifier")]
        ConceptQualifier,

        /// <summary>
        /// qualifies the elements within a specific submodel on concept level; the
        /// corresponding qualifier value is static.
        /// </summary>
        /// <remarks>
        /// Template qualifiers are only applicable to elements with kind
        /// <see cref="Our.ModellingKind.Template" />.
        /// </remarks>
        [EnumMember(Value = "TemplateQualifier")]
        TemplateQualifier
    }

    /// <summary>
    /// A qualifier is essentially a type-value-pair. Depending on the kind of
    /// qualifier, it makes additional statements:
    /// </summary>
    /// <remarks>
    /// <ul>
    ///   <li>
    ///     w.r.t. the value of the qualified element,
    ///   </li>
    ///   <li>
    ///     w.r.t. the concept, i.e. semantic definition of the qualified element,
    ///   </li>
    ///   <li>
    ///     w.r.t. existence and other meta information of the qualified element type.
    ///   </li>
    /// </ul>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     Constraint AASd-006:
    ///     If both the <see cref="Our.Qualifier.Value" /> and the <see cref="Our.Qualifier.ValueId" /> of
    ///     a <see cref="Our.Qualifier" /> are present then the <see cref="Our.Qualifier.Value" /> needs
    ///     to be identical to the value of the referenced coded value
    ///     in <see cref="Our.Qualifier.ValueId" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-020:
    ///     The value of <see cref="Our.Qualifier.Value" /> shall be consistent with the data type as
    ///     defined in <see cref="Our.Qualifier.ValueType" />.
    ///   </li>
    /// </ul>
    /// </remarks>
    public interface IQualifier : IHasSemantics
    {
        /// <summary>
        /// The qualifier kind describes the kind of qualifier that is applied to the
        /// element.
        /// </summary>
        /// <remarks>
        /// Default: <see cref="Our.QualifierKind.ConceptQualifier" />
        /// </remarks>
        public QualifierKind? Kind { get; set; }

        /// <summary>
        /// The qualifier <em>type</em> describes the type of qualifier that is applied to
        /// the element.
        /// </summary>
        public string Type { get; set; }

        /// <summary>
        /// Data type of the qualifier value.
        /// </summary>
        public DataTypeDefXsd ValueType { get; set; }

        /// <summary>
        /// The qualifier value is the value of the qualifier.
        /// </summary>
        public string? Value { get; set; }

        /// <summary>
        /// Reference to the global unique ID of a coded value.
        /// </summary>
        public IReference? ValueId { get; set; }

        public QualifierKind KindOrDefault();
    }

    /// <summary>
    /// A qualifier is essentially a type-value-pair. Depending on the kind of
    /// qualifier, it makes additional statements:
    /// </summary>
    /// <remarks>
    /// <ul>
    ///   <li>
    ///     w.r.t. the value of the qualified element,
    ///   </li>
    ///   <li>
    ///     w.r.t. the concept, i.e. semantic definition of the qualified element,
    ///   </li>
    ///   <li>
    ///     w.r.t. existence and other meta information of the qualified element type.
    ///   </li>
    /// </ul>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     Constraint AASd-006:
    ///     If both the <see cref="Our.Qualifier.Value" /> and the <see cref="Our.Qualifier.ValueId" /> of
    ///     a <see cref="Our.Qualifier" /> are present then the <see cref="Our.Qualifier.Value" /> needs
    ///     to be identical to the value of the referenced coded value
    ///     in <see cref="Our.Qualifier.ValueId" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-020:
    ///     The value of <see cref="Our.Qualifier.Value" /> shall be consistent with the data type as
    ///     defined in <see cref="Our.Qualifier.ValueType" />.
    ///   </li>
    /// </ul>
    /// </remarks>
    public class Qualifier : IQualifier
    {
        /// <summary>
        /// Identifier of the semantic definition of the element. It is called semantic ID
        /// of the element or also main semantic ID of the element.
        /// </summary>
        public IReference? SemanticId { get; set; }

        /// <summary>
        /// Identifier of a supplemental semantic definition of the element.
        /// It is called supplemental semantic ID of the element.
        /// </summary>
        public List<IReference>? SupplementalSemanticIds { get; set; }

        /// <summary>
        /// The qualifier kind describes the kind of qualifier that is applied to the
        /// element.
        /// </summary>
        /// <remarks>
        /// Default: <see cref="Our.QualifierKind.ConceptQualifier" />
        /// </remarks>
        public QualifierKind? Kind { get; set; }

        /// <summary>
        /// The qualifier <em>type</em> describes the type of qualifier that is applied to
        /// the element.
        /// </summary>
        public string Type { get; set; }

        /// <summary>
        /// Data type of the qualifier value.
        /// </summary>
        public DataTypeDefXsd ValueType { get; set; }

        /// <summary>
        /// The qualifier value is the value of the qualifier.
        /// </summary>
        public string? Value { get; set; }

        /// <summary>
        /// Reference to the global unique ID of a coded value.
        /// </summary>
        public IReference? ValueId { get; set; }

        /// <summary>
        /// Iterate over SupplementalSemanticIds, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IReference> OverSupplementalSemanticIdsOrEmpty()
        {
            return SupplementalSemanticIds
                ?? System.Linq.Enumerable.Empty<IReference>();
        }

        public QualifierKind KindOrDefault()
        {
            if (this.Kind != null)
            {
                return this.Kind!.Value;
            }
            return Our.QualifierKind.ConceptQualifier;
        }

        /// <summary>
        /// Iterate over all the class instances referenced from this instance
        /// without further recursion.
        /// </summary>
        public IEnumerable<IClass> DescendOnce()
        {
            if (SemanticId != null)
            {
                yield return SemanticId;
            }

            if (SupplementalSemanticIds != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IReference(
                        SupplementalSemanticIds))
                {
                    yield return anItem;
                }
            }

            if (ValueId != null)
            {
                yield return ValueId;
            }
        }

        /// <summary>
        /// Iterate recursively over all the class instances referenced from this instance.
        /// </summary>
        public IEnumerable<IClass> Descend()
        {
            if (SemanticId != null)
            {
                yield return SemanticId;

                // Recurse
                foreach (var anItem in SemanticId.Descend())
                {
                    yield return anItem;
                }
            }

            if (SupplementalSemanticIds != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_IReference(
                        SupplementalSemanticIds))
                {
                    yield return anItem;
                }
            }

            if (ValueId != null)
            {
                yield return ValueId;

                // Recurse
                foreach (var anItem in ValueId.Descend())
                {
                    yield return anItem;
                }
            }
        }

        /// <summary>
        /// Accept the <paramref name="visitor" /> to visit this instance
        /// for double dispatch.
        /// </summary>
        public void Accept(Visitation.IVisitor visitor)
        {
            visitor.VisitQualifier(this);
        }

        /// <summary>
        /// Accept the visitor to visit this instance for double dispatch
        /// with the <paramref name="context" />.
        /// </summary>
        public void Accept<TContext>(
            Visitation.IVisitorWithContext<TContext> visitor,
            TContext context)
        {
            visitor.VisitQualifier(this, context);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to transform this instance
        /// for double dispatch.
        /// </summary>
        public T Transform<T>(Visitation.ITransformer<T> transformer)
        {
            return transformer.TransformQualifier(this);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to visit this instance
        /// for double dispatch with the <paramref name="context" />.
        /// </summary>
        public T Transform<TContext, T>(
            Visitation.ITransformerWithContext<TContext, T> transformer,
            TContext context)
        {
            return transformer.TransformQualifier(this, context);
        }

        public Qualifier(
            string type,
            DataTypeDefXsd valueType,
            IReference? semanticId = null,
            List<IReference>? supplementalSemanticIds = null,
            QualifierKind? kind = null,
            string? value = null,
            IReference? valueId = null)
        {
            SemanticId = semanticId;
            SupplementalSemanticIds = supplementalSemanticIds;
            Type = type;
            ValueType = valueType;
            Kind = kind;
            Value = value;
            ValueId = valueId;
        }
    }

