    /// <summary>
    /// An entity is a submodel element that is used to model entities.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     Constraint AASd-014:
    ///     Either the attribute <see cref="Our.Entity.GlobalAssetId" /> or <see cref="Our.Entity.SpecificAssetIds" />
    ///     of an <see cref="Our.Entity" /> must be set if Entity/entityType is set to <see cref="Our.EntityType.SelfManagedEntity" />.
    ///   </li>
    /// </ul>
    /// </remarks>
    public interface IEntity : ISubmodelElement
    {
        /// <summary>
        /// Statement applicable to the entity, each statement described by a
        /// <see cref="Our.ISubmodelElement" /> - typically with a qualified value.
        /// </summary>
        public List<ISubmodelElement>? Statements { get; set; }

        /// <summary>
        /// Describes whether the entity is a co-managed entity or a self-managed entity.
        /// </summary>
        public EntityType? EntityType { get; set; }

        /// <summary>
        /// Global identifier of the asset the entity is representing.
        /// </summary>
        public string? GlobalAssetId { get; set; }

        /// <summary>
        /// Reference to a specific asset ID representing a supplementary identifier
        /// of the asset represented by the Asset Administration Shell.
        /// </summary>
        public List<ISpecificAssetId>? SpecificAssetIds { get; set; }

        /// <summary>
        /// Iterate over Statements, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<ISubmodelElement> OverStatementsOrEmpty();

        /// <summary>
        /// Iterate over SpecificAssetIds, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<ISpecificAssetId> OverSpecificAssetIdsOrEmpty();
    }

