        /// <summary>
        /// <see cref="Our.IHasSemantics.SemanticId" /> of the referable which defines the scope of
        /// the event, if available.
        /// </summary>
        /// <remarks>
        /// It is recommended to use an external reference.
        /// </remarks>
        public IReference? ObservableSemanticId { get; set; }

        /// <summary>
        /// Information for the outer message infrastructure to schedule the event for
        /// the respective communication channel.
        /// </summary>
        public string? Topic { get; set; }

        /// <summary>
        /// Subject, who/which initiated the creation.
        /// </summary>
        /// <remarks>
        /// This is an external reference.
        /// </remarks>
        public IReference? SubjectId { get; set; }

        /// <summary>
        /// Timestamp in UTC, when this event was triggered.
        /// </summary>
        public string TimeStamp { get; set; }

        /// <summary>
        /// Event-specific payload.
        /// </summary>
        public byte[]? Payload { get; set; }

        /// <summary>
        /// Iterate over all the class instances referenced from this instance
        /// without further recursion.
        /// </summary>
        public IEnumerable<IClass> DescendOnce()
        {
            yield return Source;

            if (SourceSemanticId != null)
            {
                yield return SourceSemanticId;
            }

            yield return ObservableReference;

            if (ObservableSemanticId != null)
            {
                yield return ObservableSemanticId;
            }

            if (SubjectId != null)
            {
                yield return SubjectId;
            }
        }

        /// <summary>
        /// Iterate recursively over all the class instances referenced from this instance.
        /// </summary>
        public IEnumerable<IClass> Descend()
        {
            yield return Source;

            // Recurse
            foreach (var anItem in Source.Descend())
            {
                yield return anItem;
            }

            if (SourceSemanticId != null)
            {
                yield return SourceSemanticId;

                // Recurse
                foreach (var anItem in SourceSemanticId.Descend())
                {
                    yield return anItem;
                }
            }

            yield return ObservableReference;

            // Recurse
            foreach (var anItem in ObservableReference.Descend())
            {
                yield return anItem;
            }

            if (ObservableSemanticId != null)
            {
                yield return ObservableSemanticId;

                // Recurse
                foreach (var anItem in ObservableSemanticId.Descend())
                {
                    yield return anItem;
                }
            }

            if (SubjectId != null)
            {
                yield return SubjectId;

                // Recurse
                foreach (var anItem in SubjectId.Descend())
                {
                    yield return anItem;
                }
            }
        }

