        /// <summary>
        /// Iterate over all the class instances referenced from this instance
        /// without further recursion.
        /// </summary>
        public IEnumerable<IClass> DescendOnce()
        {
            if (Extensions != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IExtension(
                        Extensions))
                {
                    yield return anItem;
                }
            }

            if (DisplayName != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_ILangStringNameType(
                        DisplayName))
                {
                    yield return anItem;
                }
            }

            if (Description != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_ILangStringTextType(
                        Description))
                {
                    yield return anItem;
                }
            }

            if (SemanticId != null)
            {
                yield return SemanticId;
            }

            if (SupplementalSemanticIds != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IReference(
                        SupplementalSemanticIds))
                {
                    yield return anItem;
                }
            }

            if (Qualifiers != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IQualifier(
                        Qualifiers))
                {
                    yield return anItem;
                }
            }

            if (EmbeddedDataSpecifications != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IEmbeddedDataSpecification(
                        EmbeddedDataSpecifications))
                {
                    yield return anItem;
                }
            }

            yield return Observed;

            if (MessageBroker != null)
            {
                yield return MessageBroker;
            }
        }

        /// <summary>
        /// Iterate recursively over all the class instances referenced from this instance.
        /// </summary>
        public IEnumerable<IClass> Descend()
        {
            if (Extensions != null)
            {
                foreach (var anItem in Descent.Descend_ListOf_IExtension(Extensions))
                {
                    yield return anItem;
                }
            }

            if (DisplayName != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_ILangStringNameType(
                        DisplayName))
                {
                    yield return anItem;
                }
            }

            if (Description != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_ILangStringTextType(
                        Description))
                {
                    yield return anItem;
                }
            }

            if (SemanticId != null)
            {
                yield return SemanticId;

                // Recurse
                foreach (var anItem in SemanticId.Descend())
                {
                    yield return anItem;
                }
            }

            if (SupplementalSemanticIds != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_IReference(
                        SupplementalSemanticIds))
                {
                    yield return anItem;
                }
            }

            if (Qualifiers != null)
            {
                foreach (var anItem in Descent.Descend_ListOf_IQualifier(Qualifiers))
                {
                    yield return anItem;
                }
            }

            if (EmbeddedDataSpecifications != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_IEmbeddedDataSpecification(
                        EmbeddedDataSpecifications))
                {
                    yield return anItem;
                }
            }

            yield return Observed;

            // Recurse
            foreach (var anItem in Observed.Descend())
            {
                yield return anItem;
            }

            if (MessageBroker != null)
            {
                yield return MessageBroker;

                // Recurse
                foreach (var anItem in MessageBroker.Descend())
                {
                    yield return anItem;
                }
            }
        }

