            IReference? semanticId = null,
            List<IReference>? supplementalSemanticIds = null,
            List<IQualifier>? qualifiers = null,
            List<IEmbeddedDataSpecification>? embeddedDataSpecifications = null)
        {
            Extensions = extensions;
            IdShort = idShort;
            DisplayName = displayName;
            Category = category;
            Description = description;
            SemanticId = semanticId;
            SupplementalSemanticIds = supplementalSemanticIds;
            Qualifiers = qualifiers;
            EmbeddedDataSpecifications = embeddedDataSpecifications;
        }
    }

    /// <summary>
    /// The semantics of a property or other elements that may have a semantic description
    /// is defined by a concept description.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The description of the concept should follow a standardized schema (realized as
    /// data specification template).
    /// </para>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-004:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>PROPERTY</c> or
    ///     <c>VALUE</c> using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> is mandatory and shall be
    ///     one of: <c>DATE</c>, <c>STRING</c>, <c>STRING_TRANSLATABLE</c>, <c>INTEGER_MEASURE</c>,
    ///     <c>INTEGER_COUNT</c>, <c>INTEGER_CURRENCY</c>, <c>REAL_MEASURE</c>, <c>REAL_COUNT</c>,
    ///     <c>REAL_CURRENCY</c>, <c>BOOLEAN</c>, <c>RATIONAL</c>, <c>RATIONAL_MEASURE</c>,
    ///     <c>TIME</c>, <c>TIMESTAMP</c>.
    ///     </para>
    ///     <para>
    ///     Note: categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-005:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>REFERENCE</c>
    ///     using data specification template IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> shall be
    ///     one of: <c>STRING</c>, <c>IRI</c>, <c>IRDI</c>.
    ///     </para>
    ///     <para>
    ///     Note: categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-006:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>DOCUMENT</c>
    ///     using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> shall be one of <c>FILE</c>,
    ///     <c>BLOB</c>, <c>HTML</c>
    ///     </para>
    ///     <para>
    ///     Categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-007:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>QUALIFIER_TYPE</c>
    ///     using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> is mandatory and shall be
    ///     defined.
    ///     </para>
    ///     <para>
    ///     Categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-008:
    ///     For a <see cref="Our.ConceptDescription" /> using data specification template IEC61360,
    ///     <see cref="Our.DataSpecificationIec61360.Definition" /> is mandatory and shall be
    ///     defined at least in English.
    ///     </para>
    ///     <para>
    ///     Exception: The concept description describes a value, i.e.
    ///     <see cref="Our.DataSpecificationIec61360.Value" /> is defined.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASc-3a-003:
    ///     For a <see cref="Our.ConceptDescription" /> using data specification template IEC61360,
    ///     referenced via <see cref="Our.DataSpecificationIec61360.ValueList" />
    ///     <see cref="Our.ValueReferencePair.ValueId" />
    ///     the <see cref="Our.DataSpecificationIec61360.Value" /> shall be set.
    ///   </li>
    /// </ul>
    /// </remarks>
    public interface IConceptDescription :
            IIdentifiable,
            IHasDataSpecification
    {
        /// <summary>
        /// Reference to an external definition the concept is compatible to or was derived
        /// from.
        /// </summary>
        /// <remarks>
        /// Compare with is-case-of relationship in ISO 13584-32 &amp; IEC EN 61360
        /// </remarks>
        public List<IReference>? IsCaseOf { get; set; }

        /// <summary>
        /// Iterate over IsCaseOf, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IReference> OverIsCaseOfOrEmpty();
    }

    /// <summary>
    /// The semantics of a property or other elements that may have a semantic description
    /// is defined by a concept description.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The description of the concept should follow a standardized schema (realized as
    /// data specification template).
    /// </para>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-004:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>PROPERTY</c> or
    ///     <c>VALUE</c> using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> is mandatory and shall be
    ///     one of: <c>DATE</c>, <c>STRING</c>, <c>STRING_TRANSLATABLE</c>, <c>INTEGER_MEASURE</c>,
    ///     <c>INTEGER_COUNT</c>, <c>INTEGER_CURRENCY</c>, <c>REAL_MEASURE</c>, <c>REAL_COUNT</c>,
    ///     <c>REAL_CURRENCY</c>, <c>BOOLEAN</c>, <c>RATIONAL</c>, <c>RATIONAL_MEASURE</c>,
    ///     <c>TIME</c>, <c>TIMESTAMP</c>.
    ///     </para>
    ///     <para>
    ///     Note: categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-005:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>REFERENCE</c>
    ///     using data specification template IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> shall be
    ///     one of: <c>STRING</c>, <c>IRI</c>, <c>IRDI</c>.
    ///     </para>
    ///     <para>
    ///     Note: categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-006:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>DOCUMENT</c>
    ///     using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> shall be one of <c>FILE</c>,
    ///     <c>BLOB</c>, <c>HTML</c>
    ///     </para>
    ///     <para>
    ///     Categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-007:
    ///     For a <see cref="Our.ConceptDescription" /> with <see cref="Our.ConceptDescription.Category" /> <c>QUALIFIER_TYPE</c>
    ///     using data specification IEC61360,
    ///     the <see cref="Our.DataSpecificationIec61360.DataType" /> is mandatory and shall be
    ///     defined.
    ///     </para>
    ///     <para>
    ///     Categories are deprecated since V3.0 of Part 1a of the document series
    ///     "Details of the Asset Administration Shell".
    ///     </para>
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASc-3a-008:
    ///     For a <see cref="Our.ConceptDescription" /> using data specification template IEC61360,
    ///     <see cref="Our.DataSpecificationIec61360.Definition" /> is mandatory and shall be
    ///     defined at least in English.
    ///     </para>
    ///     <para>
    ///     Exception: The concept description describes a value, i.e.
    ///     <see cref="Our.DataSpecificationIec61360.Value" /> is defined.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASc-3a-003:
    ///     For a <see cref="Our.ConceptDescription" /> using data specification template IEC61360,
    ///     referenced via <see cref="Our.DataSpecificationIec61360.ValueList" />
    ///     <see cref="Our.ValueReferencePair.ValueId" />
    ///     the <see cref="Our.DataSpecificationIec61360.Value" /> shall be set.
    ///   </li>
    /// </ul>
    /// </remarks>
    public class ConceptDescription : IConceptDescription
    {
        /// <summary>
        /// An extension of the element.
        /// </summary>
        public List<IExtension>? Extensions { get; set; }

        /// <summary>
        /// The category is a value that gives further meta information
        /// w.r.t. the class of the element.
        /// It affects the expected existence of attributes and the applicability of
        /// constraints.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The category is not identical to the semantic definition
        /// (<see cref="Our.IHasSemantics" />) of an element. The category could e.g. denote that
        /// the element is a measurement value, whereas the semantic definition of
        /// the element would denote that it is the measured temperature.
        /// </para>
        /// <para>
        /// Deprecated.
        /// </para>
        /// </remarks>
        public string? Category { get; set; }

        /// <summary>
        /// In case of identifiables, this attribute is a short name of the element.
        /// In case of a referable, this ID is an identifying string of the element within
        /// its name space.
        /// </summary>
        /// <remarks>
        /// In case the element is a property and the property has a semantic definition
        /// (<see cref="Our.IHasSemantics.SemanticId" />) conformant to IEC61360
        /// the <see cref="Our.IReferable.IdShort" /> is typically identical to the short name in English,
        /// if available.
        /// </remarks>
        public string? IdShort { get; set; }

        /// <summary>
        /// Display name. Can be provided in several languages.
        /// </summary>
        public List<ILangStringNameType>? DisplayName { get; set; }

        /// <summary>
        /// Description or comments on the element.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The description can be provided in several languages.
        /// </para>
        /// <para>
        /// If no description is defined, the definition of the concept
        /// description that defines the semantics of the element is used.
        /// </para>
        /// <para>
        /// Additional information can be provided, e.g., if the element is
        /// qualified and which qualifier types can be expected in which
        /// context or which additional data specification templates.
        /// </para>
        /// </remarks>
        public List<ILangStringTextType>? Description { get; set; }

        /// <summary>
        /// Administrative information of an identifiable element.
        /// </summary>
        /// <remarks>
        /// Some of the administrative information like the version number might need to
        /// be part of the identification.
        /// </remarks>
        public IAdministrativeInformation? Administration { get; set; }

        /// <summary>
        /// The globally unique identification of the element.
        /// </summary>
        public string Id { get; set; }

        /// <summary>
        /// Embedded data specification.
        /// </summary>
        public List<IEmbeddedDataSpecification>? EmbeddedDataSpecifications { get; set; }

        /// <summary>
        /// Reference to an external definition the concept is compatible to or was derived
        /// from.
        /// </summary>
        /// <remarks>
        /// Compare with is-case-of relationship in ISO 13584-32 &amp; IEC EN 61360
        /// </remarks>
        public List<IReference>? IsCaseOf { get; set; }

        /// <summary>
        /// Iterate over Extensions, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IExtension> OverExtensionsOrEmpty()
        {
            return Extensions
                ?? System.Linq.Enumerable.Empty<IExtension>();
        }

        /// <summary>
        /// Iterate over DisplayName, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<ILangStringNameType> OverDisplayNameOrEmpty()
        {
            return DisplayName
                ?? System.Linq.Enumerable.Empty<ILangStringNameType>();
        }

        /// <summary>
        /// Iterate over Description, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<ILangStringTextType> OverDescriptionOrEmpty()
        {
            return Description
                ?? System.Linq.Enumerable.Empty<ILangStringTextType>();
        }

        /// <summary>
        /// Iterate over EmbeddedDataSpecifications, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IEmbeddedDataSpecification> OverEmbeddedDataSpecificationsOrEmpty()
        {
            return EmbeddedDataSpecifications
                ?? System.Linq.Enumerable.Empty<IEmbeddedDataSpecification>();
        }

        /// <summary>
        /// Iterate over IsCaseOf, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IReference> OverIsCaseOfOrEmpty()
        {
            return IsCaseOf
                ?? System.Linq.Enumerable.Empty<IReference>();
        }

        /// <summary>
        /// Iterate over all the class instances referenced from this instance
        /// without further recursion.
        /// </summary>
        public IEnumerable<IClass> DescendOnce()
        {
            if (Extensions != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IExtension(
                        Extensions))
                {
                    yield return anItem;
                }
            }

            if (DisplayName != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_ILangStringNameType(
                        DisplayName))
                {
                    yield return anItem;
                }
            }

            if (Description != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_ILangStringTextType(
                        Description))
                {
                    yield return anItem;
                }
            }

            if (Administration != null)
            {
                yield return Administration;
            }

            if (EmbeddedDataSpecifications != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IEmbeddedDataSpecification(
                        EmbeddedDataSpecifications))
                {
                    yield return anItem;
                }
            }

            if (IsCaseOf != null)
            {
                foreach (
                    var anItem in Descent.DescendOnce_ListOf_IReference(
                        IsCaseOf))
                {
                    yield return anItem;
                }
            }
        }

        /// <summary>
        /// Iterate recursively over all the class instances referenced from this instance.
        /// </summary>
        public IEnumerable<IClass> Descend()
        {
            if (Extensions != null)
            {
                foreach (var anItem in Descent.Descend_ListOf_IExtension(Extensions))
                {
                    yield return anItem;
                }
            }

            if (DisplayName != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_ILangStringNameType(
                        DisplayName))
                {
                    yield return anItem;
                }
            }

            if (Description != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_ILangStringTextType(
                        Description))
                {
                    yield return anItem;
                }
            }

            if (Administration != null)
            {
                yield return Administration;

                // Recurse
                foreach (var anItem in Administration.Descend())
                {
                    yield return anItem;
                }
            }

            if (EmbeddedDataSpecifications != null)
            {
                foreach (
                    var anItem in Descent.Descend_ListOf_IEmbeddedDataSpecification(
                        EmbeddedDataSpecifications))
                {
                    yield return anItem;
                }
            }

            if (IsCaseOf != null)
            {
                foreach (var anItem in Descent.Descend_ListOf_IReference(IsCaseOf))
                {
                    yield return anItem;
                }
            }
        }

        /// <summary>
        /// Accept the <paramref name="visitor" /> to visit this instance
        /// for double dispatch.
        /// </summary>
        public void Accept(Visitation.IVisitor visitor)
        {
            visitor.VisitConceptDescription(this);
        }

        /// <summary>
        /// Accept the visitor to visit this instance for double dispatch
        /// with the <paramref name="context" />.
        /// </summary>
        public void Accept<TContext>(
            Visitation.IVisitorWithContext<TContext> visitor,
            TContext context)
        {
            visitor.VisitConceptDescription(this, context);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to transform this instance
        /// for double dispatch.
        /// </summary>
        public T Transform<T>(Visitation.ITransformer<T> transformer)
        {
            return transformer.TransformConceptDescription(this);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to visit this instance
        /// for double dispatch with the <paramref name="context" />.
        /// </summary>
        public T Transform<TContext, T>(
            Visitation.ITransformerWithContext<TContext, T> transformer,
            TContext context)
        {
            return transformer.TransformConceptDescription(this, context);
        }

        public ConceptDescription(
            string id,
            List<IExtension>? extensions = null,
            string? category = null,
            string? idShort = null,
            List<ILangStringNameType>? displayName = null,
            List<ILangStringTextType>? description = null,
            IAdministrativeInformation? administration = null,
            List<IEmbeddedDataSpecification>? embeddedDataSpecifications = null,
            List<IReference>? isCaseOf = null)
        {
            Extensions = extensions;
            IdShort = idShort;
            DisplayName = displayName;
            Category = category;
            Description = description;
            Id = id;
            Administration = administration;
            EmbeddedDataSpecifications = embeddedDataSpecifications;
            IsCaseOf = isCaseOf;
        }
    }

    /// <summary>
    /// Enumeration for denoting whether an element is an external or model reference.
    /// </summary>
    public enum ReferenceTypes
    {
        /// <summary>
        /// External reference.
        /// </summary>
        [EnumMember(Value = "ExternalReference")]
        ExternalReference,

        /// <summary>
        /// Model reference.
        /// </summary>
        [EnumMember(Value = "ModelReference")]
        ModelReference
    }

    /// <summary>
    /// Reference to either a model element of the same or another Asset Administration
    /// Shell or to an external entity.
    /// </summary>
    /// <remarks>
    /// <para>
    /// A model reference is an ordered list of keys, each key referencing an element. The
    /// complete list of keys may for example be concatenated to a path that gives
    /// unique access to an element.
    /// </para>
    /// <para>
    /// An external reference is a reference to an external entity.
    /// </para>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     Constraint AASd-121:
    ///     For <see cref="Our.Reference" />'s the value of <see cref="Our.Key.Type" /> of the first key of "
    ///     <see cref="Our.Reference.Keys" /> shall be one of <see cref="Our.Constants.GloballyIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-122:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />, the value
    ///     of <see cref="Our.Key.Type" /> of the first key of <see cref="Our.Reference.Keys" /> shall be one of
    ///     <see cref="Our.Constants.GenericGloballyIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-123:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, the value
    ///     of <see cref="Our.Key.Type" /> of the first key of <see cref="Our.Reference.Keys" /> shall be one of
    ///     <see cref="Our.Constants.AasIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-124:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />, the last
    ///     key of <see cref="Our.Reference.Keys" /> shall be either one of
    ///     <see cref="Our.Constants.GenericGloballyIdentifiables" /> or one of
    ///     <see cref="Our.Constants.GenericFragmentKeys" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-137:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />,
    ///     the value of <see cref="Our.Key.Type" /> of any key in <see cref="Our.Reference.Keys" />
    ///     shall not be one of <see cref="Our.Constants.AasReferables" />.
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASd-125:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> the value of <see cref="Our.Key.Type" />
    ///     of each of the keys following the first
    ///     key of <see cref="Our.Reference.Keys" /> shall be one of <see cref="Our.Constants.FragmentKeys" />.
    ///     </para>
    ///     <para>
    ///     Constraint AASd-125 ensures that the shortest path is used.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASd-126:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> the value of <see cref="Our.Key.Type" />
    ///     of the last key in the reference key chain may be
    ///     one of <see cref="Our.Constants.GenericFragmentKeys" /> or no key at all
    ///     shall have a value out of <see cref="Our.Constants.GenericFragmentKeys" />.
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASd-127:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> a key with <see cref="Our.Key.Type" />
    ///     <see cref="Our.KeyTypes.FragmentReference" /> shall be preceded by a key with
    ///     <see cref="Our.Key.Type" /> <see cref="Our.KeyTypes.File" /> or <see cref="Our.KeyTypes.Blob" />. All other
    ///     AAS fragments, i.e. <see cref="Our.Key.Type" /> values
    ///     out of <see cref="Our.Constants.AasSubmodelElementsAsKeys" />, do not support fragments.
    ///     </para>
    ///     <para>
    ///     Which kind of fragments are supported depends on the content type and the
    ///     specification of allowed fragment identifiers for the corresponding resource
    ///     being referenced via the reference.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASd-128:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, the
    ///     <see cref="Our.Key.Value" /> of a <see cref="Our.Key" /> preceded by a <see cref="Our.Key" /> with
    ///     <see cref="Our.Key.Type" /> = <see cref="Our.KeyTypes.SubmodelElementList" /> is an integer
    ///     number denoting the position in the array of the submodel element list.
    ///   </li>
    /// </ul>
    /// </remarks>
    public interface IReference : IClass
    {
        /// <summary>
        /// Type of the reference.
        /// </summary>
        /// <remarks>
        /// Denotes whether the reference is an external reference or a model reference.
        /// </remarks>
        public ReferenceTypes Type { get; set; }

        /// <summary>
        /// Expected <see cref="Our.IHasSemantics.SemanticId" /> of the referenced model element
        /// (<see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />); there
        /// typically is no semantic ID for the referenced object of external references
        /// (<see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />).
        /// </summary>
        /// <remarks>
        /// If <see cref="Our.Reference.ReferredSemanticId" /> is defined, the
        /// <see cref="Our.IHasSemantics.SemanticId" /> of the model element referenced should
        /// have a matching semantic ID. If this is not the case, a validator should
        /// raise a warning.
        /// </remarks>
        public IReference? ReferredSemanticId { get; set; }

        /// <summary>
        /// Unique references in their name space.
        /// </summary>
        public List<IKey> Keys { get; set; }
    }

    /// <summary>
    /// Reference to either a model element of the same or another Asset Administration
    /// Shell or to an external entity.
    /// </summary>
    /// <remarks>
    /// <para>
    /// A model reference is an ordered list of keys, each key referencing an element. The
    /// complete list of keys may for example be concatenated to a path that gives
    /// unique access to an element.
    /// </para>
    /// <para>
    /// An external reference is a reference to an external entity.
    /// </para>
    /// <para>
    /// Constraints:
    /// </para>
    /// <ul>
    ///   <li>
    ///     Constraint AASd-121:
    ///     For <see cref="Our.Reference" />'s the value of <see cref="Our.Key.Type" /> of the first key of "
    ///     <see cref="Our.Reference.Keys" /> shall be one of <see cref="Our.Constants.GloballyIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-122:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />, the value
    ///     of <see cref="Our.Key.Type" /> of the first key of <see cref="Our.Reference.Keys" /> shall be one of
    ///     <see cref="Our.Constants.GenericGloballyIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-123:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, the value
    ///     of <see cref="Our.Key.Type" /> of the first key of <see cref="Our.Reference.Keys" /> shall be one of
    ///     <see cref="Our.Constants.AasIdentifiables" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-124:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />, the last
    ///     key of <see cref="Our.Reference.Keys" /> shall be either one of
    ///     <see cref="Our.Constants.GenericGloballyIdentifiables" /> or one of
    ///     <see cref="Our.Constants.GenericFragmentKeys" />.
    ///   </li>
    ///   <li>
    ///     Constraint AASd-137:
    ///     For external references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />,
    ///     the value of <see cref="Our.Key.Type" /> of any key in <see cref="Our.Reference.Keys" />
    ///     shall not be one of <see cref="Our.Constants.AasReferables" />.
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASd-125:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> the value of <see cref="Our.Key.Type" />
    ///     of each of the keys following the first
    ///     key of <see cref="Our.Reference.Keys" /> shall be one of <see cref="Our.Constants.FragmentKeys" />.
    ///     </para>
    ///     <para>
    ///     Constraint AASd-125 ensures that the shortest path is used.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASd-126:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> the value of <see cref="Our.Key.Type" />
    ///     of the last key in the reference key chain may be
    ///     one of <see cref="Our.Constants.GenericFragmentKeys" /> or no key at all
    ///     shall have a value out of <see cref="Our.Constants.GenericFragmentKeys" />.
    ///   </li>
    ///   <li>
    ///     <para>
    ///     Constraint AASd-127:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, with more
    ///     than one key in <see cref="Our.Reference.Keys" /> a key with <see cref="Our.Key.Type" />
    ///     <see cref="Our.KeyTypes.FragmentReference" /> shall be preceded by a key with
    ///     <see cref="Our.Key.Type" /> <see cref="Our.KeyTypes.File" /> or <see cref="Our.KeyTypes.Blob" />. All other
    ///     AAS fragments, i.e. <see cref="Our.Key.Type" /> values
    ///     out of <see cref="Our.Constants.AasSubmodelElementsAsKeys" />, do not support fragments.
    ///     </para>
    ///     <para>
    ///     Which kind of fragments are supported depends on the content type and the
    ///     specification of allowed fragment identifiers for the corresponding resource
    ///     being referenced via the reference.
    ///     </para>
    ///   </li>
    ///   <li>
    ///     Constraint AASd-128:
    ///     For model references, i.e. <see cref="Our.Reference" />'s with
    ///     <see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />, the
    ///     <see cref="Our.Key.Value" /> of a <see cref="Our.Key" /> preceded by a <see cref="Our.Key" /> with
    ///     <see cref="Our.Key.Type" /> = <see cref="Our.KeyTypes.SubmodelElementList" /> is an integer
    ///     number denoting the position in the array of the submodel element list.
    ///   </li>
    /// </ul>
    /// </remarks>
    public class Reference : IReference
    {
        /// <summary>
        /// Type of the reference.
        /// </summary>
        /// <remarks>
        /// Denotes whether the reference is an external reference or a model reference.
        /// </remarks>
        public ReferenceTypes Type { get; set; }

        /// <summary>
        /// Expected <see cref="Our.IHasSemantics.SemanticId" /> of the referenced model element
        /// (<see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ModelReference" />); there
        /// typically is no semantic ID for the referenced object of external references
        /// (<see cref="Our.Reference.Type" /> = <see cref="Our.ReferenceTypes.ExternalReference" />).
        /// </summary>
        /// <remarks>
        /// If <see cref="Our.Reference.ReferredSemanticId" /> is defined, the
        /// <see cref="Our.IHasSemantics.SemanticId" /> of the model element referenced should
        /// have a matching semantic ID. If this is not the case, a validator should
        /// raise a warning.
        /// </remarks>
        public IReference? ReferredSemanticId { get; set; }

        /// <summary>
        /// Unique references in their name space.
        /// </summary>
        public List<IKey> Keys { get; set; }

        /// <summary>
        /// Iterate over all the class instances referenced from this instance
        /// without further recursion.
        /// </summary>
        public IEnumerable<IClass> DescendOnce()
        {
            if (ReferredSemanticId != null)
            {
                yield return ReferredSemanticId;
            }

            foreach (var anItem in Descent.DescendOnce_ListOf_IKey(Keys))
            {
                yield return anItem;
            }
        }

        /// <summary>
        /// Iterate recursively over all the class instances referenced from this instance.
        /// </summary>
        public IEnumerable<IClass> Descend()
        {
            if (ReferredSemanticId != null)
            {
                yield return ReferredSemanticId;

                // Recurse
                foreach (var anItem in ReferredSemanticId.Descend())
                {
                    yield return anItem;
                }
            }

            foreach (var anItem in Descent.Descend_ListOf_IKey(Keys))
            {
                yield return anItem;
            }
        }

        /// <summary>
        /// Accept the <paramref name="visitor" /> to visit this instance
        /// for double dispatch.
        /// </summary>
        public void Accept(Visitation.IVisitor visitor)
        {
            visitor.VisitReference(this);
        }

        /// <summary>
        /// Accept the visitor to visit this instance for double dispatch
        /// with the <paramref name="context" />.
        /// </summary>
        public void Accept<TContext>(
            Visitation.IVisitorWithContext<TContext> visitor,
            TContext context)
        {
            visitor.VisitReference(this, context);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to transform this instance
        /// for double dispatch.
        /// </summary>
        public T Transform<T>(Visitation.ITransformer<T> transformer)
        {
            return transformer.TransformReference(this);
        }

        /// <summary>
        /// Accept the <paramref name="transformer" /> to visit this instance
        /// for double dispatch with the <paramref name="context" />.
        /// </summary>
        public T Transform<TContext, T>(
            Visitation.ITransformerWithContext<TContext, T> transformer,
            TContext context)
        {
            return transformer.TransformReference(this, context);
        }

        public Reference(
            ReferenceTypes type,
            List<IKey> keys,
            IReference? referredSemanticId = null)
        {
            Type = type;
            Keys = keys;
            ReferredSemanticId = referredSemanticId;
        }
    }

    /// <summary>
    /// A key is a reference to an element by its ID.
    /// </summary>
    public interface IKey : IClass
    {
        /// <summary>
        /// Denotes which kind of entity is referenced.
        /// </summary>
        /// <remarks>
        /// <para>
        /// If <see cref="Our.Key.Type" /> = <see cref="Our.KeyTypes.GlobalReference" />,
        /// the key represents a reference to a source that can be globally identified.
        /// </para>
        /// <para>
        /// If <see cref="Our.Key.Type" /> = <see cref="Our.KeyTypes.FragmentReference" /> the key represents
        /// a bookmark or a similar local identifier within its parent element as specified
        /// by the key that precedes this key.
        /// </para>
        /// <para>
        /// In all other cases, the key references a model element of the same or another
        /// Asset Administration Shell.
        /// The name of the model element is explicitly listed.
        /// </para>
        /// </remarks>
        public KeyTypes Type { get; set; }

        /// <summary>
        /// The key value, for example an IRDI or a URI or the ID-short or any other
        /// fragment value
        /// </summary>
        public string Value { get; set; }
    }

