    /// <summary>
    /// Enumeration listing selected XSD anySimpleTypes of XML Schema 1.0.
    /// </summary>
    /// <remarks>
    /// <para>
    /// See: https://www.w3.org/TR/xmlschema-2/#built-in-primitive-datatypes
    /// </para>
    /// <para>
    /// <para>
    /// RDF uses XML Schema Built-in data types from Version 1.1 but recommends
    /// to use only a subset of XSD data types. That is why they are excluded
    /// from the allowed data types in <see cref="Our.DataTypeDefXsd" />.
    /// </para>
    /// <ul>
    ///   <li>
    ///     XSD BuildIn List types are not supported (<c>ENTITIES</c>, <c>IDREFS</c>
    ///     and <c>NMTOKENS</c>).
    ///   </li>
    ///   <li>
    ///     XSD string BuildIn types are not supported (<c>normalizedString</c>,
    ///     <c>token</c>, <c>language</c>, <c>NCName</c>, <c>ENTITY</c>, <c>ID</c>, <c>IDREF</c>).
    ///   </li>
    ///   <li>
    ///     The following XSD primitive types are not supported: <c>NOTATION</c>,
    ///     <c>QName</c>.
    ///   </li>
    /// </ul>
    /// </para>
    /// <para>
    /// Additionally, the following RDF types are not supported in
    /// <see cref="Our.DataTypeDefXsd" />: <c>HTML</c> and <c>XMLLiteral</c>.
    /// </para>
    /// <para>
    /// Numeric data types in XML Schema are based on the definitions of
    /// IEEE 754 with slight adoptions. For instance, <see cref="Our.DataTypeDefXsd.Float" /> and
    /// <see cref="Our.DataTypeDefXsd.Double" /> use different exponent ranges. In any case, solely
    /// the XML Schema data type definitions are applicable for AAS values.
    /// </para>
    /// </remarks>
    public enum DataTypeDefXsd
    {
        [EnumMember(Value = "xs:anyURI")]
        AnyUri,

        [EnumMember(Value = "xs:base64Binary")]
        Base64Binary,

        [EnumMember(Value = "xs:boolean")]
        Boolean,

        [EnumMember(Value = "xs:byte")]
        Byte,

        [EnumMember(Value = "xs:date")]
        Date,

        [EnumMember(Value = "xs:dateTime")]
        DateTime,

        [EnumMember(Value = "xs:decimal")]
        Decimal,

        [EnumMember(Value = "xs:double")]
        Double,

        [EnumMember(Value = "xs:duration")]
        Duration,

        [EnumMember(Value = "xs:float")]
        Float,

        [EnumMember(Value = "xs:gDay")]
        GDay,

        [EnumMember(Value = "xs:gMonth")]
        GMonth,

        [EnumMember(Value = "xs:gMonthDay")]
        GMonthDay,

        [EnumMember(Value = "xs:gYear")]
        GYear,

        [EnumMember(Value = "xs:gYearMonth")]
        GYearMonth,

        [EnumMember(Value = "xs:hexBinary")]
        HexBinary,

        [EnumMember(Value = "xs:int")]
        Int,

        [EnumMember(Value = "xs:integer")]
        Integer,

        [EnumMember(Value = "xs:long")]
        Long,

        [EnumMember(Value = "xs:negativeInteger")]
        NegativeInteger,

        [EnumMember(Value = "xs:nonNegativeInteger")]
        NonNegativeInteger,

        [EnumMember(Value = "xs:nonPositiveInteger")]
        NonPositiveInteger,

        [EnumMember(Value = "xs:positiveInteger")]
        PositiveInteger,

        [EnumMember(Value = "xs:short")]
        Short,

        [EnumMember(Value = "xs:string")]
        String,

        [EnumMember(Value = "xs:time")]
        Time,

        [EnumMember(Value = "xs:unsignedByte")]
        UnsignedByte,

        [EnumMember(Value = "xs:unsignedInt")]
        UnsignedInt,

        [EnumMember(Value = "xs:unsignedLong")]
        UnsignedLong,

        [EnumMember(Value = "xs:unsignedShort")]
        UnsignedShort
    }

