        /// </summary>
        public T Transform<TContext, T>(
            Visitation.ITransformerWithContext<TContext, T> transformer,
            TContext context)
        {
            return transformer.TransformValueReferencePair(this, context);
        }

        public ValueReferencePair(
            string value,
            IReference? valueId = null)
        {
            Value = value;
            ValueId = valueId;
        }
    }

