        /// Iterate over Definition, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<IDefinitionTypeUom> OverDefinitionOrEmpty();

        /// <summary>
        /// Iterate over PreferredNameQuantity, if set, and otherwise return an empty enumerable.
        /// </summary>
        public IEnumerable<ILangStringUom> OverPreferredNameQuantityOrEmpty();
